package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"

	"github.com/avro/go-avro"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run <program> <source_file> <struct_name>")
		os.Exit(1)
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	err := readStructDefinition(sourceFile, structName)
	if err != nil {
		fmt.Printf("Error reading struct definition: %v\n", err)
		return
	}

	// Generate Avro schema
	schema, err := avro.GenerateSchemaFromFile(filepath.Join(sourceFile, "schema.go"))
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
		return
	}

	fmt.Println(schema)
}

func readStructDefinition(filePath string, structName string) error {
	file, err := os.Open(filePath)
	if err != nil {
		return fmt.Errorf("failed to open file: %w", err)
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := scanner.Text()
		if line == `type = "{`+structName+"}"` {
			return fmt.Errorf("struct definition not found")
		}
	}

	if err := scanner.Err(); err != nil {
		return fmt.Errorf("scanner failed: %w", err)
	}

	return nil
}
```

### Explanation:

1. **Program Execution**: The program expects three command-line arguments:
   - `<source_file>`: The path to the Go source file.
   - `<struct_name>`: The name of the struct you want to convert.

2. **Reading Struct Definition**:
   - The `readStructDefinition` function attempts to find the struct definition in the given Go source file.
   - It looks for the type declaration for the specified struct using regular expressions.
   - If the struct definition is found, the function returns without further processing.

3. **Generating Avro Schema**:
   - Once the struct definition is successfully parsed, the program calls the `GenerateSchemaFromFile` method to create an Avro schema based on the struct definition.
   - The generated schema is then printed to the console.

4. **Error Handling**:
   - The program includes basic error handling for file opening, scanning, and parsing errors.

### Usage Example:

Assume you have a Go source file called `my_struct.go` with the following content:

```go
package my_package

type MyStruct struct {
	Name  string
 Age   int
}
```

To generate an Avro schema for this struct, you would run the program like so:

```sh
